import{_ as t,a as d,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse(`{"title":"Revoke a GDPR Request","description":"","frontmatter":{"outline":false,"examples":[{"id":"revoke-gdpr-request","title":"Revoke a GDPR Request","description":"Withdraw a pending or processing GDPR data request owned by the authenticated customer.","query":"mutation RevokeGdprRequest($id: ID!) {\\n  revokeGdprRequest(\\n    input: {\\n      id: $id\\n    }\\n  ) {\\n    gdprRequest {\\n      _id\\n      type\\n      status\\n      message\\n      email\\n      revokedAt\\n      createdAt\\n      updatedAt\\n      successMessage\\n      customer {\\n        _id\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/shop/gdpr-requests/12\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"revokeGdprRequest\\": {\\n      \\"gdprRequest\\": {\\n        \\"_id\\": 12,\\n        \\"type\\": \\"delete\\",\\n        \\"status\\": \\"revoked\\",\\n        \\"message\\": \\"Please delete my account data.\\",\\n        \\"email\\": \\"jane@example.com\\",\\n        \\"revokedAt\\": \\"2026-06-25T11:05:00+00:00\\",\\n        \\"createdAt\\": \\"2026-06-25T10:30:00+00:00\\",\\n        \\"updatedAt\\": \\"2026-06-25T11:05:00+00:00\\",\\n        \\"successMessage\\": \\"Your GDPR data request has been revoked successfully.\\",\\n        \\"customer\\": {\\n          \\"_id\\": 7\\n        }\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"GDPR disabled","cause":"GDPR data requests are turned off in the store's admin configuration","solution":"Re-enable GDPR from the admin configuration before revoking a request"},{"error":"cannot revoke","cause":"The request is not in a pending or processing state","solution":"Only pending or processing requests can be revoked"},{"error":"NOT_FOUND","cause":"The request does not exist or is not owned by the authenticated customer","solution":"Only request IDs belonging to the logged-in customer can be revoked"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/gdpr-requests/mutations/revoke-gdpr-request.md","filePath":"api/graphql-api/shop/gdpr-requests/mutations/revoke-gdpr-request.md","lastUpdated":1786429091000}`),o={name:"api/graphql-api/shop/gdpr-requests/mutations/revoke-gdpr-request.md"};function s(n,e,i,u,c,p){return r(),d("div",null,e[0]||(e[0]=[a('<h1 id="revoke-a-gdpr-request" tabindex="-1">Revoke a GDPR Request <a class="header-anchor" href="#revoke-a-gdpr-request" aria-label="Permalink to &quot;Revoke a GDPR Request&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>revokeGdprRequest</code> mutation withdraws a GDPR data request the customer raised earlier. Revoking sets the request&#39;s status to <code>revoked</code> and stamps <code>revokedAt</code>. A request can only be revoked while it is still <code>pending</code> or <code>processing</code> — once it has been declined or approved it can no longer be revoked. The result carries a one-time <code>successMessage</code>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="gdpr-must-be-enabled" tabindex="-1">GDPR must be enabled <a class="header-anchor" href="#gdpr-must-be-enabled" aria-label="Permalink to &quot;GDPR must be enabled&quot;">​</a></h2><p>If GDPR data requests are disabled in the store&#39;s admin configuration, the mutation fails with the message <strong>&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</strong> in <code>errors[]</code>. The feature has been turned off on the admin side.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>✅ Yes</td><td>The request IRI, e.g. <code>/api/shop/gdpr-requests/12</code>.</td></tr><tr><td><code>clientMutationId</code></td><td><code>String</code></td><td>❌ No</td><td>Arbitrary string echoed back in the payload.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>gdprRequest._id</code></td><td><code>Int!</code></td><td>Numeric request ID.</td></tr><tr><td><code>gdprRequest.type</code></td><td><code>String!</code></td><td>Request type: <code>delete</code> or <code>update</code>.</td></tr><tr><td><code>gdprRequest.status</code></td><td><code>String!</code></td><td>Request status — <code>revoked</code> after a successful revoke.</td></tr><tr><td><code>gdprRequest.message</code></td><td><code>String!</code></td><td>The message supplied in the request.</td></tr><tr><td><code>gdprRequest.email</code></td><td><code>String!</code></td><td>Email address tied to the request.</td></tr><tr><td><code>gdprRequest.revokedAt</code></td><td><code>String</code></td><td>Timestamp when the request was revoked.</td></tr><tr><td><code>gdprRequest.createdAt</code></td><td><code>String</code></td><td>Request creation timestamp.</td></tr><tr><td><code>gdprRequest.updatedAt</code></td><td><code>String</code></td><td>Request last update timestamp.</td></tr><tr><td><code>gdprRequest.successMessage</code></td><td><code>String</code></td><td>Confirmation message — present on create / revoke / delete results.</td></tr><tr><td><code>gdprRequest.customer</code></td><td><code>Customer</code></td><td>The customer who owns the request.</td></tr><tr><td><code>gdprRequest.customer._id</code></td><td><code>Int!</code></td><td>Numeric customer ID of the owner.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/gdpr-requests/mutations/create-gdpr-request.html">Raise a GDPR Request</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/mutations/delete-gdpr-request.html">Delete a GDPR Request</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/">GDPR Requests Overview</a></li></ul>',13)]))}const q=t(o,[["render",s]]);export{h as __pageData,q as default};
